import os
import json
from pathlib import Path

# First, let's check what policy documents are available
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() and file.endswith(('.txt', '.json', '.md', '.pdf')):
        policy_files.append(file)

print("Found policy files:", policy_files)

# Read each policy document
policies = {}
for policy_file in policy_files:
    try:
        if policy_file.endswith('.json'):
            with open(policy_file, 'r') as f:
                policies[policy_file] = json.load(f)
        else:
            with open(policy_file, 'r') as f:
                policies[policy_file] = f.read()
        print(f"\nSuccessfully read: {policy_file}")
    except Exception as e:
        print(f"Error reading {policy_file}: {e}")

# Display basic info about each policy
print("\n" + "="*50)
print("POLICY DOCUMENT ANALYSIS")
print("="*50)

for filename, content in policies.items():
    print(f"\nFile: {filename}")
    if isinstance(content, dict):
        print(f"Type: JSON with keys: {list(content.keys())}")
        # Check for authority indicators in JSON
        if 'authoritative' in str(content).lower() or 'primary' in str(content).lower():
            print("  Contains authority indicators")
    else:
        print(f"Type: Text ({len(content)} characters)")
        # Check for authority indicators in text
        authority_indicators = ['authoritative', 'primary', 'official', 'master', 'definitive', 'final']
        found_indicators = [ind for ind in authority_indicators if ind in content.lower()]
        if found_indicators:
            print(f"  Contains authority indicators: {found_indicators}")

    # Check metadata like file naming
    if 'master' in filename.lower() or 'primary' in filename.lower() or 'official' in filename.lower():
        print(f"  File naming suggests authority")
